import{_ as d,o,c as r,a2 as e}from"./chunks/framework.CnHmQiA8.js";const p=JSON.parse('{"title":"常见问题与主题设置","description":"","frontmatter":{"title":"常见问题与主题设置","outline":[2,3]},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1795437342000}'),a={name:"guide/faq.md"};function n(s,t,c,l,i,g){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="常见问题与主题设置" tabindex="-1">常见问题与主题设置 <a class="header-anchor" href="#常见问题与主题设置" aria-label="Permalink to &quot;常见问题与主题设置&quot;">​</a></h1><h2 id="_1-软件设置与配色主题" tabindex="-1">1. 软件设置与配色主题 <a class="header-anchor" href="#_1-软件设置与配色主题" aria-label="Permalink to &quot;1. 软件设置与配色主题&quot;">​</a></h2><p>在首页左侧栏点击 <strong>设置…</strong>，可以配置以下全局偏好：</p><ul><li><strong>教学案库位置</strong>：指定 <code>.tplan</code> 工程与自制模板的默认存放目录。</li><li><strong>导入时默认格式预设</strong>：从 Word 文档新建或快速导入时默认采用的预设。</li><li><strong>公式字母默认正斜体</strong>：设置新建教学案时公式字母默认正体还是斜体。</li><li><strong>默认导出知识点重点难点汇总</strong>：开启后每次导出 Word 默认同时输出 <code>(T)名称(知识点重点难点).docx</code>。</li><li><strong>WorkBuddy 自动识别</strong>：点击一次 <strong>连接 WorkBuddy</strong> 完成本机配置。</li><li><strong>配色主题</strong>（点击立即生效并自动记住）：</li></ul><div class="info custom-block"><p class="custom-block-title">主题只改软件界面，不影响排版与导出</p><p>无论切换到深色模式还是风格主题，中间的 A4 预览纸面始终保持白纸黑字，导出的 Word 文档也完全不受软件界面主题影响。</p></div><h3 id="七套内置配色主题" tabindex="-1">七套内置配色主题 <a class="header-anchor" href="#七套内置配色主题" aria-label="Permalink to &quot;七套内置配色主题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题名称</th><th>类型</th><th>视觉风格说明</th></tr></thead><tbody><tr><td><strong>青灰</strong>（默认）</td><td>常规</td><td>安静的青灰工作台，配以克制的“批改红”强调色</td></tr><tr><td><strong>暖纸</strong></td><td>常规</td><td>柔和的米色纸面与偏棕墨色</td></tr><tr><td><strong>雾蓝</strong></td><td>常规</td><td>偏冷调的蓝灰工作台</td></tr><tr><td><strong>素白</strong></td><td>常规</td><td>不带色相的中性灰白，接近常见办公软件风格</td></tr><tr><td><strong>深色</strong></td><td>常规</td><td>暗色面板与工作台（公式输入框仍保持白底黑字便于核对）</td></tr><tr><td><strong>赤黑</strong></td><td>风格主题</td><td>红黑白高反差、直角与斜切色块、剪报拼贴标题、悬停游移四边形、斜幕切页以及预览右键“战斗指令”式菜单</td></tr><tr><td><strong>月潮</strong></td><td>风格主题</td><td>深海蓝与青色辉光、逐字浮起标题、流光按钮以及三层海水灌入的标签页切换过场</td></tr></tbody></table><p>选择“赤黑”或“月潮”后，“配色”下方会出现每项动效的独立开关，你可以按喜好关闭某一项（改回常规效果）；当系统开启“减弱动态效果”时，动画也会自动关闭。</p><h2 id="_2-常用快捷键速查" tabindex="-1">2. 常用快捷键速查 <a class="header-anchor" href="#_2-常用快捷键速查" aria-label="Permalink to &quot;2. 常用快捷键速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><strong>首页文件列表</strong></td><td><code>Enter</code></td><td>打开选中教学案（或用 Word 新建教学案）</td></tr><tr><td><strong>首页文件列表</strong></td><td><code>F2</code></td><td>重命名教学案并同步修改 <code>.tplan</code> 文件名</td></tr><tr><td><strong>首页文件列表</strong></td><td><code>Delete</code></td><td>将文件移到系统回收站</td></tr><tr><td><strong>全局标签页</strong></td><td><code>Ctrl+Tab</code> / <code>Ctrl+Shift+Tab</code></td><td>切换到下一个 / 上一个已打开的教学案标签页</td></tr><tr><td><strong>全局标签页</strong></td><td><code>Ctrl+W</code>（或鼠标中键）</td><td>关闭当前教学案标签页</td></tr><tr><td><strong>编辑界面</strong></td><td><code>Ctrl+E</code></td><td>打开导出 Word 对话框</td></tr><tr><td><strong>编辑界面</strong></td><td><code>Ctrl+Z</code> / <code>Ctrl+Y</code> / <code>Ctrl+Shift+Z</code></td><td>撤销 / 重做（最多 200 步）</td></tr><tr><td><strong>文字输入</strong></td><td><code>Ctrl+B</code> / <code>Ctrl+I</code> / <code>Ctrl+U</code></td><td>加粗 / 倾斜 / 下划线</td></tr><tr><td><strong>选项图片缩放</strong></td><td><code>Shift + 拖动右下角</code></td><td>全部选项图片一起等比缩放</td></tr><tr><td><strong>表格单元格选择</strong></td><td><code>Shift + 单击另一格</code></td><td>选中矩形区域以便合并单元格</td></tr><tr><td><strong>大纲拖拽</strong></td><td><code>Esc</code></td><td>取消当前拖拽排序</td></tr></tbody></table><h2 id="_3-常见使用问题" tabindex="-1">3. 常见使用问题 <a class="header-anchor" href="#_3-常见使用问题" aria-label="Permalink to &quot;3. 常见使用问题&quot;">​</a></h2><h3 id="导出的-word-可以发给没有安装本软件的老师打开吗" tabindex="-1">导出的 Word 可以发给没有安装本软件的老师打开吗？ <a class="header-anchor" href="#导出的-word-可以发给没有安装本软件的老师打开吗" aria-label="Permalink to &quot;导出的 Word 可以发给没有安装本软件的老师打开吗？&quot;">​</a></h3><p>可以。导出的是标准的 <code>.docx</code> 文档，题号、小问号与 <code>【答案】</code> 使用 Word 自动编号，公式为 Word 原生公式，表格为 Word 原生表格。其他老师无需安装本软件，用 Microsoft Word 或 WPS 即可直接打开和二次修改。</p><h3 id="tplan-工程文件如何备份或分享给同事" tabindex="-1"><code>.tplan</code> 工程文件如何备份或分享给同事？ <a class="header-anchor" href="#tplan-工程文件如何备份或分享给同事" aria-label="Permalink to &quot;`.tplan` 工程文件如何备份或分享给同事？&quot;">​</a></h3><p><code>.tplan</code> 是独立的单文件工程（内部为标准 ZIP 容器，所有题目、公式与插图图片都打包在里面）。直接把 <code>.tplan</code> 文件复制给同事，或者把整个「教学案库」文件夹同步备份即可。</p><h3 id="windows-macos-安装后首次打开被系统拦截怎么办" tabindex="-1">Windows / macOS 安装后首次打开被系统拦截怎么办？ <a class="header-anchor" href="#windows-macos-安装后首次打开被系统拦截怎么办" aria-label="Permalink to &quot;Windows / macOS 安装后首次打开被系统拦截怎么办？&quot;">​</a></h3><p>由于软件为开源独立打包发布、未购买商业代码签名证书，Windows 遇 SmartScreen 拦截时点击 <strong>更多信息 → 仍要运行</strong>；macOS 遇“无法验证开发者”时进入 <strong>系统设置 → 隐私与安全性</strong> 点击 <strong>仍要打开</strong> 即可，详见 <a href="/Teaching-plan-production/download.html#安装注意事项">下载安装说明</a>。</p><h3 id="从墨案导入时遇到登录卡住或页面白屏怎么办" tabindex="-1">从墨案导入时遇到登录卡住或页面白屏怎么办？ <a class="header-anchor" href="#从墨案导入时遇到登录卡住或页面白屏怎么办" aria-label="Permalink to &quot;从墨案导入时遇到登录卡住或页面白屏怎么办？&quot;">​</a></h3><p>在墨案导入窗口的顶部 <strong>页面</strong> 菜单中，可以依次尝试 <strong>强制刷新（忽略缓存）</strong>、<strong>清除登录状态与缓存并刷新</strong>；如果某篇教案导入失败，可点击 <strong>导入 → 保存诊断文件</strong>（已自动隐去登录凭证）以便定位问题。</p>',19)])])}const u=d(a,[["render",n]]);export{p as __pageData,u as default};
